import { createContext, useState } from "react";

export const AppContext = createContext();

export function AppProvider({ children }) {
  const [role, setRole] = useState(null);
  const [username, setUsername] = useState("");

  function login(r,u,p) {
    if (r==="admin" && u==="admin" && p==="admin") {
      setRole("admin");
    } else if (r==="user") {
      setRole("user");
      setUsername(u);
    }
  }

  function logout() {
    setRole(null);
    setUsername("");
  }

  return (
    <AppContext.Provider value={{ role, username, login, logout }}>
      {children}
    </AppContext.Provider>
  );
}
